dtsPropsFor.AnswerDiff:
/** The graded result to explain, from `checkAnswer` in lib/diff. */
check: {
  /** certo = exact; quase = accent/case slip; incompleto = words missing; errado = a word is wrong. */
  verdict: "certo" | "quase" | "incompleto" | "errado";
  /** What the learner wrote, marked up word by word. */
  attempt: { text: string; status: "same" | "wrong" | "missing" | "extra" }[];
  /** The correct answer, marked up word by word. */
  target: { text: string; status: "same" | "wrong" | "missing" | "extra" }[];
};
/** The grader already called this a near-miss — keep that framing. */
nearMiss?: boolean;
className?: string;
